import unittest

from solucao import maiusculas
from solucao import minusculas


class TestMaiusculasEMinusculas(unittest.TestCase):
    def test_maiusculas_deixa_tudo_grande(self):
        """maiusculas devolve o texto com letras grandes"""
        self.assertEqual(maiusculas("ola"), "OLA")

    def test_maiusculas_converte_o_numero(self):
        """maiusculas converte o numero para texto"""
        self.assertEqual(maiusculas(2026), "2026")

    def test_minusculas_deixa_tudo_pequeno(self):
        """minusculas devolve o texto com letras pequenas"""
        self.assertEqual(minusculas("OLA"), "ola")

    def test_minusculas_com_numero_no_meio(self):
        """minusculas deixa o numero como esta"""
        self.assertEqual(minusculas("OLA 123"), "ola 123")

